import itertools

def solve():
    n = 6
    vertices = list(range(n))
    triangles = list(itertools.combinations(vertices, 3))

    # A (6, 3, 2) design has 10 triangles.
    # Every edge must be in 2 triangles.
    # There are 15 edges in K6.
    # Total "edge-triangle" count = 10 * 3 = 30.
    # Each of the 15 edges must be in 30/15 = 2 triangles.

    for design in itertools.combinations(triangles, 10):
        # Check if each edge is in 2 triangles
        edges = list(itertools.combinations(vertices, 2))
        is_design = True
        for edge in edges:
            count = 0
            for tri in design:
                if edge[0] in tri and edge[1] in tri:
                    count += 1
            if count != 2:
                is_design = False
                break

        if is_design:
            # For this design, check all 2-colorings of vertices
            # r + b = 6. Possible (r, b) are (0,6), (1,5), (2,4), (3,3).
            # Since we want to minimize monochromatic triangles, we only need to check (3,3).
            # Actually, let's check all of them.
            for r in range(n + 1):
                b = n - r
                # All ways to choose r vertices to be Red
                for red_vertices in itertools.combinations(vertices, r):
                    red_set = set(red_vertices)
                    mono_count = 0
                    for tri in design:
                        if tri[0] in red_set and tri[1] in red_set and tri[2] in red_set:
                            mono_count += 1
                        elif tri[0] not in red_set and tri[1] not in red_set and tri[2] not in red_set:
                            mono_count += 1

                    if mono_count < 2:
                        return f"Found design with {mono_count} monochromatic triangles for n=6"
    return "No such design found for n=6"

