import itertools

def check_fano_plane():
    points = range(7)
    lines = [
        (0, 1, 2), (0, 3, 4), (0, 5, 6),
        (1, 3, 5), (1, 4, 6), (2, 3, 6), (2, 4, 5)
    ]

    # For each coloring (R=3, B=4)
    for red_points in itertools.combinations(points, 3):
        red_set = set(red_points)
        blue_set = set(points) - red_set

        mono_triangles = 0
        for line in lines:
            if all(p in red_set for p in line):
                mono_triangles += 1
            elif all(p in blue_set for p in line):
                mono_triangles += 1

        if mono_triangles < 2:
            return mono_triangles
    return "All colorings have >= 2"

print(check_fano_plane())
